from __future__ import annotations
import base64, shutil
from datetime import datetime
from pathlib import Path

MODULE="alliance_v4_failure_forensics_v434f.py"
REG="alliance_optional_property_modules.py"
DATA=""

def chk(p):
    compile(p.read_text(encoding="utf-8"), str(p), "exec")

def main():
    r=Path.cwd()
    required=[
        "alliance_autonomous_student_v434.py",
        "alliance_autonomous_student_v433.py",
        "alliance_autonomous_student_v432.py",
        "alliance_autonomous_student_v431.py",
        "alliance_autonomous_student_v430.py",
        "alliance_cre_academy_v402.py",
        REG,
    ]
    missing=[x for x in required if not (r/x).exists()]
    if missing:
        raise SystemExit("Missing cumulative files: "+", ".join(missing))

    v434=(r/"alliance_autonomous_student_v434.py").read_text(encoding="utf-8")
    for marker in [
        'VERSION = "4.3.4-ALLIANCE-AUTONOMOUS-STUDENT-V5-DEMAND-OWNERSHIP-CLOSURE"',
        "V434_TRAINING_HOLD_DO_NOT_FREEZE_V5",
        "V434_DEMAND_FIRST_CLASS_OWNERSHIP",
    ]:
        if marker not in v434:
            raise SystemExit("Current 4.3.4 source differs; refusing blind forensic install: "+marker)

    reg=r/REG
    old=reg.read_text(encoding="utf-8")
    bak=r/f"{REG}.before-v434f-{datetime.now().strftime('%Y%m%d-%H%M%S')}.bak"
    shutil.copy2(reg,bak)

    (r/MODULE).write_text(base64.b64decode(DATA).decode(), encoding="utf-8")

    marker="# FOUNDATION 4.3.4F - Exact V4 Failure Forensics"
    if marker not in old:
        pos=old.rfind("    return result")
        if pos<0:
            raise SystemExit("Registrar return not found; no changes made.")
        block=r"""
    # FOUNDATION 4.3.4F - Exact V4 Failure Forensics
    # Read-only forensic route. No student changes. No V5 freeze.
    try:
        if _route_exists(app, "/api/property-brain/autonomous-v434-forensics/status"):
            result["v434_forensics"] = {"status":"ALREADY_REGISTERED","route":"/property-brain/autonomous-v434-forensics","error":None}
        else:
            import alliance_v4_failure_forensics_v434f as v434_forensics
            result["v434_forensics"] = {**v434_forensics.register(core), "error": None}
    except Exception as exc:
        result["v434_forensics"] = {"status":"ERROR","error":f"{type(exc).__name__}: {exc}","route":"/property-brain/autonomous-v434-forensics","fail_safe":True}

"""
        reg.write_text(old[:pos]+block+old[pos:], encoding="utf-8")

    chk(r/MODULE)
    chk(reg)

    txt=reg.read_text(encoding="utf-8")
    checks={
        "v430":"autonomous_v430" in txt,
        "v431":"autonomous_v431" in txt,
        "v432":"autonomous_v432" in txt,
        "v433":"autonomous_v433" in txt,
        "v434":"autonomous_v434" in txt,
        "v434f":"v434_forensics" in txt,
    }
    if not all(checks.values()):
        raise SystemExit("Cumulative verification failed: "+repr(checks))

    print("Alliance V4 Failure Forensics 4.3.4F installed")
    print("Student changes: 0")
    print("V5 freeze: 0")
    print("Production/WhatsApp/Gold writes: 0")
    print("Dashboard: /property-brain/autonomous-v434-forensics")
    print("Backup:", bak)

if __name__=="__main__":
    main()
